#include <iostream>
#include <fstream>
#include <omniORB4/CORBA.h>

#include "echo.hh" // Generated by the IDL compiler

int main(int argc, char* argv[])
{
  try
    {
      CORBA::ORB_var orb = CORBA::ORB_init(argc, argv);
      std::ifstream ior_file("message.ior");
      std::string ior_string;
      if (ior_file.is_open())
	{
	  std::getline(ior_file, ior_string);
	  ior_file.close();
        }
      else
	{
	  std::cerr << "Unable to open message.ior file" << std::endl;
	  return 1;
        }
      CORBA::Object_var obj = orb->string_to_object(ior_string.c_str());
      MessageModule::Echo_var echo_ref = MessageModule::Echo::_narrow(obj);
      if (CORBA::is_nil(echo_ref))
	{
	  std::cerr << "Invalid object reference." << std::endl;
	  return 1;
        }
      MessageModule::MyMessage my_message;
      my_message.id = 123;
      my_message.text = CORBA::string_dup("Custom message test");
      MessageModule::MyMessage_var result = echo_ref->echoMessage(my_message);
      std::cout << "Received message: ID=" << result->id << ", Text=" << result->text << std::endl;
      orb->destroy();
    }
  catch (CORBA::Exception& ex)
    {
      std::cerr << "CORBA exception: " << ex._name() << std::endl;
      return 1;
    }
  return 0;
}
